def kmer_counts(seq: str, k: int) -> dict[str, int]:
    """Occurrences of every length-k window of `seq`."""
    counts: dict[str, int] = {}
    for i in range(len(seq) - k + 1):
        kmer: str = seq[i:i + k]
        counts[kmer] = counts.get(kmer, 0) + 1
    return counts

